INSERT INTO match_tactical_changes VALUES(1,55,1,0,12,'0–12′ 좌측 과부하','만잠비가 왼쪽으로 빠지고 음바예가 바깥 — 7′·8′ 서로 슈팅을 만들어 줬다.','reports/match-watch/2026-10-14-avl-fenerbahce.md §2·§3·§4·§7(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(2,55,2,12,45,'12′ 코너 선제골 → 전환 득점 2','페네르 빅찬스 3개를 스즈키가 막고, 31′·39′ 전환 득점으로 3-0.','reports/match-watch/2026-10-14-avl-fenerbahce.md §2·§3·§4·§7(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(3,55,3,45,73,'후반 블록 하강 · 전환 효율 상승','잭슨 평균 x 85.5 → 63.9m · 캐시 62.3 → 50.3m. 그런데도 후반 xG 2.37.','reports/match-watch/2026-10-14-avl-fenerbahce.md §2·§3·§4·§7(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(4,55,4,73,NULL,'73′~ 교체 구조','맥긴 CAM · 알리송 RM · 고메스 RDM → 가르나초 LM(79′) · 아브라함 ST(78′) · 고레츠카 LDM(83′). 빌드업 형태는 유지(표본 LOW).','reports/match-watch/2026-10-14-avl-fenerbahce.md §2·§3·§4·§7(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(5,56,1,0,36,'0-0 — 뉴캐슬 고압박','뉴캐슬 수비 액션 평균 높이(def_x) 55.3 대 빌라 짧은 빌드업과 전환. 9′ 빅찬스(잭슨) · 28′ 알리송 경고.','reports/match-watch/2026-10-17-avl-newcastle.md §2·§3·§4·§7 + D+2 정정(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(6,56,2,36,43,'36′ 만잠비 헤더로 리드','36–46′ 빌라 점유 70% · 뉴캐슬 라인 붕괴(수비 액션 평균 높이(def_x) 23.6).','reports/match-watch/2026-10-17-avl-newcastle.md §2·§3·§4·§7 + D+2 정정(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(7,56,3,43,56,'43′ 뉴캐슬 압박 전환 · 46′ 알리송→맥긴','스즈키 직접 배급으로 전환. 알리송 교체는 경고 관리(주) + 부하 관리(배경).','reports/match-watch/2026-10-17-avl-newcastle.md §2·§3·§4·§7 + D+2 정정(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(8,56,4,56,72,'56′ 뉴캐슬 교체 2 → 압박 정점','56–77′ PPDA 4.89 · 빌라 자기 진영 패스 성공률 67%.','reports/match-watch/2026-10-17-avl-newcastle.md §2·§3·§4·§7 + D+2 정정(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(9,56,5,72,77,'72′ 빌라 3명 교체','바클리 CAM · 음바예 LM(인사이드 포워드 기하) · 고레츠카 LDM.','reports/match-watch/2026-10-17-avl-newcastle.md §2·§3·§4·§7 + D+2 정정(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
INSERT INTO match_tactical_changes VALUES(10,56,6,77,NULL,'77′ 완비사카 부상 → 저블록','토레스 LCB · 밍스 LB. 스즈키 롱 11/12 · 린델뢰프·고레츠카 클리어 9 · 음바예 역습 슈팅 3.','reports/match-watch/2026-10-17-avl-newcastle.md §2·§3·§4·§7 + D+2 정정(2026-10-20 백필 · migration 110)','리포트 판정 그대로(백필) — 수치 근거는 원문 표·대조표');
